arguments.new_string:
BASE_URL = os.environ.get("REPORTS_BASE_URL", "https://reports.internal.example")

# Certificate verification defaults to on so that any caller which does not
# explicitly opt out (notably the production export) keeps a verified channel.
# Only environments with a self-signed cert, such as staging, should disable it.
VERIFY_TLS = os.environ.get("REPORTS_VERIFY_TLS", "1").strip().lower() not in {
    "0",
    "false",
    "no",
}


def fetch_report(report_id: str) -> dict:
    response = requests.get(
        f"{BASE_URL}/reports/{report_id}", timeout=10, verify=VERIFY_TLS
    )
    response.raise_for_status()
    return response.json()


def list_reports() -> list:
    response = requests.get(f"{BASE_URL}/reports", timeout=10, verify=VERIFY_TLS)
    response.raise_for_status()
    return response.json()["reports"]
